	return userExists && bbUser != "" && keyExists && bbKey != "" && secretExists && bbSecret != ""
}

func resolveWorkingDir(backupDir string) string {
	if w := os.Getenv(envGitWorkingDir); w != "" {
		return w
	}

	return filepath.Join(backupDir, workingDIRName)
